import sqlite3
import re

conn = sqlite3.connect('/root/data/eventlogs.db')
conn.row_factory = sqlite3.Row
cur = conn.cursor()

cur.execute("SELECT event_id, event_code, timestamp, message FROM events WHERE event_code IN (800, 4103) AND host = 'WS-05.corp.example' ORDER BY timestamp")
lines = []
for row in cur.fetchall():
    msg = row['message']
    if row['event_code'] == 800:
        for line in msg.split('\n'):
            if "Pipeline execution details" in line or "command line:" in line:
                lines.append((row['event_id'], row['timestamp'], line.strip()))
