cat << 'EOF' > parse_ps_hosts.py
import sqlite3
import re

conn = sqlite3.connect('/root/data/eventlogs.db')
conn.row_factory = sqlite3.Row
cur = conn.cursor()

cur.execute("SELECT event_id, event_code, timestamp, message FROM events WHERE event_code IN (800, 4103) AND host = 'WS-05.corp.example'")
by_host_id = {}
for row in cur.fetchall():
    msg = row['message']
    h = re.search(r'Host ID\s*=\s*(\S+)|HostId=(\S+)', msg, re.IGNORECASE)
    host_id = "unknown"
    if h:
        host_id = h.group(1) or h.group(2)
    if host_id not in by_host_id:
        by_host_id[host_id] = []
    by_host_id[host_id].append((row['event_id'], row['event_code'], row['timestamp'], msg))

for hid, evs in by_host_id.items():
    print(f"=== Host ID: {hid} | Count: {len(evs)} ===")
    # print first 10 command lines/invocations
    shown = 0
    for eid, ecode, ts, msg in evs:
        for line in msg.split('\n'):
            if "command line:" in line.lower() or "commandinvocation" in line.lower():
                print(f"  {eid} | {ts} | {line.strip()}")
                shown += 1
                if shown >= 10:
                    break
        if shown >= 10:
            break

EOF
python3 parse_ps_hosts.py
